-- Esquema heredado de cliente_datos.sqlite (drift). No modificar.
CREATE TABLE "cliente_servidores" ("id" TEXT NOT NULL, "host" TEXT NOT NULL, "puerto" INTEGER NOT NULL, "ultima_conexion" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "api_key" TEXT NULL, "tipo_credencial" TEXT NULL, "ultimo_usuario_sesion" TEXT NULL, "https" INTEGER NOT NULL DEFAULT 0 CHECK ("https" IN (0, 1)), "confiar_en_certificado" INTEGER NOT NULL DEFAULT 0 CHECK ("confiar_en_certificado" IN (0, 1)), "sesion_token_persistente" TEXT NULL, "expira_sesion_persistente" INTEGER NULL, PRIMARY KEY ("id"), UNIQUE ("host", "puerto"));

CREATE TABLE "cliente_progresos" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "servidor_id" TEXT NOT NULL REFERENCES cliente_servidores (id) ON DELETE CASCADE, "media_item_id" TEXT NOT NULL, "posicion_segundos" INTEGER NOT NULL DEFAULT 0, "estado" TEXT NOT NULL, "ultima_reproduccion" INTEGER NULL, "pista_audio_id" TEXT NULL, "pista_subtitulo_id" TEXT NULL, UNIQUE ("servidor_id", "media_item_id"));

CREATE TABLE "cliente_proximas_a_ver" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "servidor_id" TEXT NOT NULL REFERENCES cliente_servidores (id) ON DELETE CASCADE, "media_item_id" TEXT NOT NULL, "agregado_en" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), UNIQUE ("servidor_id", "media_item_id"));

CREATE TABLE "cliente_colecciones" ("id" TEXT NOT NULL, "servidor_id" TEXT NOT NULL REFERENCES cliente_servidores (id) ON DELETE CASCADE, "nombre" TEXT NOT NULL, "quitar_al_verse" INTEGER NOT NULL DEFAULT 0 CHECK ("quitar_al_verse" IN (0, 1)), "creado_en" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));

CREATE TABLE "cliente_coleccion_items" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "coleccion_id" TEXT NOT NULL REFERENCES cliente_colecciones (id) ON DELETE CASCADE, "media_item_id" TEXT NOT NULL, "agregado_en" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), UNIQUE ("coleccion_id", "media_item_id"));

CREATE TABLE "cliente_coleccion_progresos" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "coleccion_id" TEXT NOT NULL REFERENCES cliente_colecciones (id) ON DELETE CASCADE, "media_item_id" TEXT NOT NULL, "posicion_segundos" INTEGER NOT NULL DEFAULT 0, "estado" TEXT NOT NULL, "ultima_reproduccion" INTEGER NULL, "pista_audio_id" TEXT NULL, "pista_subtitulo_id" TEXT NULL, UNIQUE ("coleccion_id", "media_item_id"));
